const itemFiscalClassificationExists = `-- name: ItemFiscalClassificationExists :one
SELECT EXISTS (SELECT 1 FROM fiscal_classifications WHERE enterprise_id=$1 AND is_active
 AND valid_from<=CURRENT_DATE AND (valid_until IS NULL OR valid_until>=CURRENT_DATE)
 AND (code::text = $2::text OR ncm = $2::text))
`

type ItemFiscalClassificationExistsParams struct {
	EnterpriseID       int64
	ClassificationCode string
}

func (q *Queries) ItemFiscalClassificationExists(ctx context.Context, arg ItemFiscalClassificationExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, itemFiscalClassificationExists, arg.EnterpriseID, arg.ClassificationCode)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const itemGTINEmUso = `-- name: ItemGTINEmUso :one
SELECT business_code FROM items
WHERE enterprise_id = $1 AND accounting_gtin = $2
  AND business_code <> $3
LIMIT 1
`

type ItemGTINEmUsoParams struct {
	EnterpriseID int64
	Gtin         pgtype.Text
	BusinessCode string
}

// Outro item da empresa com o mesmo GTIN: o índice único recusaria, mas a mensagem
// precisa dizer qual é.
func (q *Queries) ItemGTINEmUso(ctx context.Context, arg ItemGTINEmUsoParams) (string, error) {
	row := q.db.QueryRow(ctx, itemGTINEmUso, arg.EnterpriseID, arg.Gtin, arg.BusinessCode)
	var business_code string
	err := row.Scan(&business_code)
	return business_code, err
}

